public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }

    int[] remainderCount = new int[k];

    for (int num : arr) {
        int remainder = ((num % k) + k) % k;
        remainderCount[remainder]++;
    }

    // For remainder 0, count must be even
    if (remainderCount[0] % 2 != 0) {
        return false;
    }

    // For each remainder i from 1 to k/2, check if count[i] == count[k-i]
    for (int i = 1; i <= k / 2; i++) {
        if (i == k - i) {
            // This happens when k is even and i = k/2
            if (remainderCount[i] % 2 != 0) {
                return false;
            }
        } else {
            if (remainderCount[i] != remainderCount[k - i]) {
                return false;
            }
        }
    }

    return true;
