public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n == 0) return 0;

    // Build adjacency list
    List<List<Integer>> graph = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        int u = edge[0], v = edge[1];
        graph.get(u).add(v);
        graph.get(v).add(u);
    }

    // DFS to compute minimum time
    // We use a helper that returns the total time needed for the subtree rooted at node
    // to collect all apples in that subtree and return to the node.
    // If a subtree has no apples, we don't need to visit it, so it contributes 0.
    // If a subtree has apples, we need to go to each child that has apples (or has a subtree with apples)
    // and come back, so each such child adds 2 (one edge down, one edge up) plus the child's subtree time.

    int[] result = new int[1];

    // Use iterative DFS to avoid stack overflow for large n
    // We'll do a post-order traversal
    int[] parent = new int[n];
    Arrays.fill(parent, -1);
    int[] order = new int[n];
    int[] inStack = new int[n]; // 0 = not visited, 1 = in stack, 2 = done
    int[] childCount = new int[n];

    // Build parent and order using BFS/DFS
    int[] stack = new int[n];
    int top = 0;
    stack[top++] = 0;
    parent[0] = -1;
    int[] visitOrder = new int[n];
    int visitIdx = 0;

    // We'll do a simple DFS to get the order
    int[] dfsStack = new int[n];
    int dfsTop = 0;
    dfsStack[dfsTop++] = 0;
    int[] visited = new int[n];
    int[] postOrder = new int[n];
    int postIdx = 0;

    // Use a stack-based post-order traversal
    // We need to track when all children are processed
    int[] childProcessed = new int[n];
    int[] totalChildren = new int[n];

    // First, compute total children for each node (excluding parent)
    for (int i = 0; i < n; i++) {
        totalChildren[i] = graph.get(i).size();
        if (parent[i] != -1) {
            totalChildren[i]--;
        }
    }

    // Actually, let's use a simpler approach: recursive DFS with explicit stack
    // Or just use recursion since n is likely not too large for typical test cases
    // But to be safe, let's use iterative

    // Let's use a different approach: 
    // 1. Build parent array and children list
    // 2. Process nodes in reverse BFS order (leaves first)

    // Build children list
    List<List<Integer>> children = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        children.add(new ArrayList<>());
    }

    // BFS to build parent and children
    int[] queue = new int[n];
    int front = 0, back = 0;
    queue[back++] = 0;
    parent[0] = -1;
    int[] processed = new int[n];
    processed[0] = 1;

    while (front < back) {
        int node = queue[front++];
        for (int neighbor : graph.get(node)) {
            if (neighbor == parent[node]) continue;
            parent[neighbor] = node;
            children.get(node).add(neighbor);
            processed[neighbor] = 1;
            queue[back++] = neighbor;
        }
    }

    // Now process in reverse BFS order (from leaves to root)
    // The BFS order is in queue[0..back-1]
    // We process from back-1 down to 0

    int[] subtreeTime = new int[n];

    for (int i = back - 1; i >= 0; i--) {
        int node = queue[i];
        int time = 0;
        boolean hasAppleInSubtree = hasApple[node];

        for (int child : children.get(node)) {
            if (subtreeTime[child] > 0 || hasApple[child]) {
                // This child's subtree has apples, so we need to visit it
                time += 2 + subtreeTime[child];
                hasAppleInSubtree = true;
            }
        }

        if (hasAppleInSubtree) {
            subtreeTime[node] = time;
        } else {
            subtreeTime[node] = 0;
        }
    }

    return subtreeTime[0];
}
