public int minOperations(int n) {
    // The array is arr[i] = 2*i + 1 for i in [0, n-1]
    // The target value to make all elements equal is the average of the array.
    // The sum of the array is sum_{i=0}^{n-1} (2*i + 1) = 2 * (n-1)*n/2 + n = n*(n-1) + n = n^2
    // So the average is n^2 / n = n.
    // The target value is n.
    // The number of operations is the sum of the positive differences (or negative differences) from the target.
    // Since the array is symmetric around the target, we can compute the sum of (target - arr[i]) for all i where arr[i] < target.
    // arr[i] = 2*i + 1 < n  =>  2*i + 1 < n  =>  i < (n-1)/2
    // For each such i, the difference is n - (2*i + 1).
    // We need to sum n - (2*i + 1) for i from 0 to floor((n-1)/2) - 1? Let's check.
    // Actually, we sum for all i where 2*i + 1 < n.
    // Let's compute the sum directly.

    // Alternative approach: The minimum number of operations is the sum of the absolute differences from the median (or mean, since we can transfer units).
    // Actually, the minimum number of operations to make all elements equal to the mean is the sum of the positive deviations (which equals the sum of the negative deviations in absolute value).
    // So we can compute: sum_{i=0}^{n-1} max(0, n - (2*i + 1))

    int target = n;
    int operations = 0;
    for (int i = 0; i < n; i++) {
        int val = 2 * i + 1;
        if (val < target) {
            operations += target - val;
        }
    }
    return operations;
}
