public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Array must not be null or empty");
    }

    int ones = 0;
    int twos = 0;

    for (int num : nums) {
        // Update twos: if num is in ones, it moves to twos
        twos |= (ones & num);
        // Update ones: if num is in twos, it moves out of ones
        ones ^= num;
        // Common bits in ones and twos should be removed (appear 3 times)
        int threes = ones & twos;
        // Remove common bits from both ones and twos
        ones &= ~threes;
        twos &= ~threes;
    }

    return ones;
}
