    long factor = 1;

    while (factor <= n) {
        long high = n / (factor * 10);
        long current = (n / factor) % 10;
        long low = n % factor;

        if (current == 0) {
            count += high * factor;
        } else if (current == 1) {
            count += high * factor + low + 1;
        } else {
            count += (high + 1) * factor;
        }

        factor *= 10;
    }

    return count;
