public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }

    int n = A.length;
    if (n == 1) {
        return 1;
    }

    // Count frequencies
    int maxVal = 0;
    for (int v : A) {
        if (v > maxVal) maxVal = v;
    }

    int[] freq = new int[maxVal + 1];
    for (int v : A) {
        freq[v]++;
    }

    // Precompute which pairs sum to a perfect square
    // Max possible sum is 2 * maxVal
    int maxSum = 2 * maxVal;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 0; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }

    // Memoization: key is (index, remaining counts encoded)
    // Since values can be up to some limit, we use a map with a string key or a custom key
    // Better: use a HashMap with a key that represents the state
    // State: the multiset of remaining elements. We can encode this as a string of counts.
    // But that might be slow. Alternative: use backtracking with memoization on the tuple of counts.

    // Let's use a different approach: since the array length is small (typically <= 15 in such problems),
    // we can use backtracking with memoization based on the sorted tuple of remaining elements.

