    sb.append(lastValue).append("|");
    for (int i = 0; i < freq.length; i++) {
        if (i > 0) sb.append(",");
        sb.append(freq[i]);
    }
    String key = sb.toString();

    if (memo.containsKey(key)) {
        return memo.get(key);
    }

    int count = 0;
    for (int i = 0; i < uniqueVals.size(); i++) {
        if (freq[i] == 0) continue;

        int val = uniqueVals.get(i);

        // Check if this value can be placed after lastValue
        if (lastValue != -1) {
            int sum = lastValue + val;
            int sqrt = (int) Math.sqrt(sum);
            if (sqrt * sqrt != sum && (sqrt + 1) * (sqrt + 1) != sum) {
                continue;
            }
        }

        // Place this value
        freq[i]--;
        count += backtrack(freq, uniqueVals, val, memo, totalN);
        freq[i]++;
    }

    memo.put(key, count);
    return count;
}
