public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }

    int maxEnergy = 1;
    int currentEnergy = 1;

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentEnergy++;
        } else {
            currentEnergy = 1;
        }
        if (currentEnergy > maxEnergy) {
            maxEnergy = currentEnergy;
        }
    }

    return maxEnergy;
